correctSolution:
def memoize(fn):
    cache = {}
    def wrapper(coins, target):
        key = (tuple(coins), target)
        if key not in cache:
            cache[key] = fn(coins, target)
        return cache[key]
    return wrapper

@memoize
def min_coins(coins, target):
    if target == 0:
        return 0
    if target < 0:
        return float('inf')
    res = float('inf')
    for c in coins:
        sub = min_coins(coins, target - c)
        if sub != float('inf'):
            res = min(res, 1 + sub)
    return res

